// FieldManual (the caveman network) — the in-app face of `bsc survival`, the offline corpus of
// survival PROCEDURES and natural REMEDIES. Authored as a RECORD, not a file (epic #3604).
//
// The component mirrors what makes the store worth having rather than re-listing it: the two lookups
// a document cannot serve. `mode="have"` runs materials -> procedures (`bsc survival have`), and the
// remedies tab crosses FUNCTION with LOCATION (`bsc survival remedy list --function --region`). It
// reads through the `bsc` bridge, so the frontend never holds a second copy of the corpus — the store
// stays the one source and this is a view of it.
//
// TWO FIELDS ARE RENDERED LOUDLY ON PURPOSE. A procedure's `limits` (what it does NOT do) and a
// remedy's `lookalikes` (with the tell that separates it from the thing that kills you) are the
// safety mechanism of the data model, and a UI that folded them into a details drawer would undo it.
import { useEffect, useMemo, useState } from "react";
import type { ReactNode } from "react";
import { bscJson } from "@/shared/lib/core/bsc";
import { Card } from "@/shared/ui/data/Card";
import { Chip } from "@/shared/ui/data/Chip";
import { Stack } from "@/shared/ui/layout/Stack";
import { Row } from "@/shared/ui/layout/Row";
import { Text } from "@/shared/ui/typography/Text";
import { Banner } from "@/shared/ui/feedback/Banner";
import { EmptyState } from "@/shared/ui/feedback/EmptyState";
import { SearchField } from "@/shared/ui/controls/SearchField";

/** One thing a procedure needs, with what else would serve. */
export interface Material {
  item: string;
  substitutes?: string[];
  optional?: boolean;
}

/** A thing you DO — mirrors the Rust `Procedure` in `crates/bsc-survival`. */
export interface Procedure {
  id: string;
  category: string;
  name: string;
  summary: string;
  time?: string;
  materials?: Material[];
  steps?: { text: string; why?: string }[];
  verify?: string[];
  /** What this does NOT do. Never optional in the store, and never hidden here. */
  limits: string[];
  cautions?: string[];
}

/** A plant that could be mistaken for a remedy, and the observable difference. */
export interface Lookalike {
  name: string;
  latin?: string;
  danger: string;
  tell: string;
}

/** A thing that GROWS with a medicinal function — mirrors the Rust `Remedy`. */
export interface Remedy {
  id: string;
  name: string;
  latin?: string;
  functions: string[];
  regions?: string[];
  habitat?: string;
  parts?: string[];
  identify?: string[];
  lookalikes?: Lookalike[];
  preparations?: { form: string; method: string; forUse?: string }[];
  cautions: string[];
  evidence?: string;
}

/** One vocabulary term with how many records carry it — `bsc survival functions` / `regions`. */
export interface Term {
  token: string;
  count: number;
}

export interface FieldManualViewProps {
  procedures: Procedure[];
  remedies: Remedy[];
  /** The function vocabulary the store actually holds, so a filter is reachable without knowing it. */
  functions: Term[];
  /** The region vocabulary, likewise. */
  regions: Term[];
  /** Active function filter (a token from `functions`), or null for all. */
  activeFunction: string | null;
  onFunction: (token: string | null) => void;
  /** Active region filter (a token from `regions`), or null for all. */
  activeRegion: string | null;
  onRegion: (token: string | null) => void;
  /** The materials-in-hand query, comma or space separated. */
  have: string;
  onHave: (value: string) => void;
  loading?: boolean;
}

/** A filter as a real TOGGLE BUTTON. `Chip` is a presentational `<span>` with no `onClick`, so
 *  hanging a click handler on one would produce a control that no keyboard can reach and no screen
 *  reader announces as pressable. The chip stays the pill; the button carries the semantics, and
 *  `aria-pressed` is what says which filter is on. */
function FilterChip({ active, onClick, children }: { active: boolean; onClick: () => void; children: ReactNode }) {
  return (
    <button
      type="button"
      aria-pressed={active}
      onClick={onClick}
      style={{ background: "none", border: "none", padding: 0, cursor: "pointer", lineHeight: 0 }}
    >
      <Chip tone={active ? "accent" : "neutral"}>{children}</Chip>
    </button>
  );
}

/** Does this remedy grow in `region`? The same rule the Rust `Remedy::grows_in` applies — exact, the
 *  `-` hierarchy in both directions, and `worldwide` answering everything. Duplicated here rather than
 *  round-tripping to the CLI on every keystroke; `fieldManual.test.tsx` pins the two agreeing. */
export function growsIn(remedy: Remedy, region: string | null): boolean {
  if (!region) return true;
  const q = region.trim().toLowerCase();
  if (!q) return true;
  return (remedy.regions ?? []).some((raw) => {
    const r = raw.toLowerCase();
    return r === "worldwide" || r === q || q.startsWith(`${r}-`) || r.startsWith(`${q}-`);
  });
}

/** Which procedures the materials in hand support, and what each is still short of. The inverse
 *  lookup, computed locally so it answers as you type; matching goes through each material's
 *  substitutes in BOTH directions, exactly as `Material::satisfied_by` does. */
export function feasible(procedures: Procedure[], have: string[]): { p: Procedure; missing: string[] }[] {
  if (have.length === 0) return [];
  const satisfied = (m: Material) =>
    have.some((raw) => {
      const h = raw.trim().toLowerCase();
      if (!h) return false;
      return [m.item, ...(m.substitutes ?? [])].some((c) => {
        const t = c.toLowerCase();
        return t.includes(h) || h.includes(t);
      });
    });
  return procedures
    .map((p) => {
      const mats = p.materials ?? [];
      const covered = mats.filter(satisfied);
      const missing = mats.filter((m) => !m.optional && !satisfied(m)).map((m) => m.item);
      return { p, missing, touched: covered.length > 0 };
    })
    .filter((r) => r.touched)
    .sort((a, b) => a.missing.length - b.missing.length || a.p.id.localeCompare(b.p.id))
    .map(({ p, missing }) => ({ p, missing }));
}

/** The manual as PURE presentation — corpus in, markup out, no bridge call. Split from the host so
 *  every filter and both lookups are testable without mocking the `bsc` bridge. */
export function FieldManualView({
  procedures, remedies, functions, regions,
  activeFunction, onFunction, activeRegion, onRegion, have, onHave, loading,
}: FieldManualViewProps) {
  const inHand = useMemo(
    () => have.split(/[,\s]+/).map((t) => t.trim()).filter(Boolean),
    [have],
  );
  const supported = useMemo(() => feasible(procedures, inHand), [procedures, inHand]);
  const shown = useMemo(
    () =>
      remedies
        .filter((r) => !activeFunction || r.functions.includes(activeFunction))
        .filter((r) => growsIn(r, activeRegion)),
    [remedies, activeFunction, activeRegion],
  );

  return (
    <Stack gap={12}>
      <Banner tone="warn" dot role="note">
        Reference documentation, not medical advice — it does not replace getting to care. Read a
        procedure&apos;s LIMITS and a remedy&apos;s LOOK-ALIKES before you act on either.
      </Banner>

      <Card title="What can I make with what I have?" hint="materials → procedures">
        <Stack gap={9}>
          <SearchField
            value={have}
            onChange={onHave}
            placeholder="bottle, charcoal, sand, tin can…"
            aria-label="Materials you have on hand"
          />
          {inHand.length === 0 ? (
            <Text size={11} tone="dim">
              Name what is in your hands. Substitutes count — a tin can answers &ldquo;metal container&rdquo;.
            </Text>
          ) : supported.length === 0 ? (
            <EmptyState
              iconVariant="dashed"
              icon="⌕"
              size="sm"
              title="Nothing in the corpus uses those"
              description="Try a broader word — 'cloth' rather than a brand of bandage."
            />
          ) : (
            <Stack gap={5}>
              {supported.map(({ p, missing }) => (
                <Row key={p.id} gap={9} align="center" data-testid={`have-${p.id}`}>
                  <Chip tone={missing.length === 0 ? "success" : undefined}>
                    {missing.length === 0 ? "ready" : `needs ${missing.length}`}
                  </Chip>
                  <Text as="span" size={11} weight={500}>{p.name}</Text>
                  {missing.length > 0 && (
                    <Text as="span" size={10} tone="dim">missing: {missing.join(", ")}</Text>
                  )}
                </Row>
              ))}
            </Stack>
          )}
        </Stack>
      </Card>

      <Card title="Remedies" hint="what it is FOR × where you are" loading={loading}>
        <Stack gap={10}>
          <Row gap={6} wrap role="group" aria-label="Filter remedies by function">
            <FilterChip active={activeFunction === null} onClick={() => onFunction(null)}>
              any function
            </FilterChip>
            {functions.map((f) => (
              <FilterChip
                key={f.token}
                active={activeFunction === f.token}
                onClick={() => onFunction(f.token)}
              >
                {f.token} · {f.count}
              </FilterChip>
            ))}
          </Row>
          <Row gap={6} wrap role="group" aria-label="Filter remedies by region">
            <FilterChip active={activeRegion === null} onClick={() => onRegion(null)}>
              anywhere
            </FilterChip>
            {regions.map((r) => (
              <FilterChip
                key={r.token}
                active={activeRegion === r.token}
                onClick={() => onRegion(r.token)}
              >
                {r.token} · {r.count}
              </FilterChip>
            ))}
          </Row>

          {shown.length === 0 ? (
            <EmptyState
              iconVariant="dashed"
              icon="✳"
              size="sm"
              title="Nothing recorded for that combination"
              description="Silence about a range is not a claim of range — widen the region, or add what grows where you are with `bsc survival upsert remedy`."
            />
          ) : (
            shown.map((r) => (
              <Card key={r.id} pad="sm">
                <Stack gap={6}>
                  <Row gap={8} align="baseline" wrap data-testid={`remedy-${r.id}`}>
                    <Text as="h4" size={12} weight={600}>{r.name}</Text>
                    {r.latin && <Text as="span" size={10} tone="dim">{r.latin}</Text>}
                  </Row>
                  <Row gap={5} wrap>
                    {r.functions.map((f) => <Chip key={f}>{f}</Chip>)}
                  </Row>
                  {r.habitat && <Text size={11} tone="muted">{r.habitat}</Text>}
                  {(r.lookalikes ?? []).map((l) => (
                    <Banner key={l.name} tone="danger" loud role="alert">
                      <Text as="span" size={11}>
                        <strong>Look-alike — {l.name}:</strong> {l.danger} <em>Tell:</em> {l.tell}
                      </Text>
                    </Banner>
                  ))}
                  {r.cautions.length > 0 && (
                    <Text size={10.5} tone="dim">Cautions: {r.cautions.join(" · ")}</Text>
                  )}
                </Stack>
              </Card>
            ))
          )}
        </Stack>
      </Card>
    </Stack>
  );
}

/** The HOST: loads the corpus and both vocabularies through the `bsc` bridge, once, and holds the
 *  filter state. The corpus is static between writes, so this is a one-shot read rather than a poll —
 *  polling a packaged corpus would spend a subprocess per interval to learn nothing. */
export function FieldManual() {
  const [procedures, setProcedures] = useState<Procedure[]>([]);
  const [remedies, setRemedies] = useState<Remedy[]>([]);
  const [functions, setFunctions] = useState<Term[]>([]);
  const [regions, setRegions] = useState<Term[]>([]);
  const [loading, setLoading] = useState(true);

  const [activeFunction, setActiveFunction] = useState<string | null>(null);
  const [activeRegion, setActiveRegion] = useState<string | null>(null);
  const [have, setHave] = useState("");

  useEffect(() => {
    let cancelled = false;
    void (async () => {
      const [p, r, f, g] = await Promise.all([
        bscJson<Procedure[]>(null, ["survival", "list", "--json"], []),
        bscJson<Remedy[]>(null, ["survival", "remedy", "list", "--json"], []),
        bscJson<Term[]>(null, ["survival", "functions", "--json"], []),
        bscJson<Term[]>(null, ["survival", "regions", "--json"], []),
      ]);
      if (cancelled) return;
      setProcedures(p);
      setRemedies(r);
      setFunctions(f);
      setRegions(g);
      setLoading(false);
    })();
    return () => { cancelled = true; };
  }, []);

  return (
    <FieldManualView
      procedures={procedures}
      remedies={remedies}
      functions={functions}
      regions={regions}
      activeFunction={activeFunction}
      onFunction={setActiveFunction}
      activeRegion={activeRegion}
      onRegion={setActiveRegion}
      have={have}
      onHave={setHave}
      loading={loading}
    />
  );
}

