import { describe, it, expect, vi } from "vitest";
import { render, screen, within } from "@testing-library/react";
import { FieldManualView, feasible, growsIn, type Procedure, type Remedy, type Term } from "./FieldManual";

const YARROW: Remedy = {
  id: "yarrow",
  name: "Yarrow",
  latin: "Achillea millefolium",
  functions: ["hemostatic", "antiseptic"],
  regions: ["north-america", "europe"],
  habitat: "Disturbed sunny ground",
  cautions: ["Asteraceae allergy"],
  lookalikes: [
    {
      name: "Poison hemlock",
      latin: "Conium maculatum",
      danger: "Lethal.",
      tell: "Hollow stem with purple blotches; yarrow's stem is solid and hairy.",
    },
  ],
};

const WITCH_HAZEL: Remedy = {
  id: "witch-hazel",
  name: "Witch hazel",
  functions: ["astringent"],
  regions: ["north-america-east"],
  cautions: ["Topical use only"],
};

const FILTER: Procedure = {
  id: "water-improvised-filter",
  category: "water",
  name: "Improvised layered filter",
  summary: "Clears cloudy water.",
  limits: ["THIS DOES NOT MAKE WATER SAFE."],
  materials: [
    { item: "plastic bottle or hollow container", substitutes: ["bottle", "sock"] },
    { item: "charcoal from a wood fire", substitutes: ["charcoal"] },
    { item: "clean sand", substitutes: ["sand"] },
  ],
};

const BOIL: Procedure = {
  id: "water-boil",
  category: "water",
  name: "Boil water",
  summary: "Kills every pathogen.",
  limits: ["Removes nothing dissolved."],
  materials: [
    { item: "metal container", substitutes: ["tin can", "pot"] },
    { item: "fire or stove", substitutes: ["fire"] },
    { item: "cloth for pre-filtering", substitutes: ["shirt"], optional: true },
  ],
};

const FUNCTIONS: Term[] = [
  { token: "hemostatic", count: 2 },
  { token: "astringent", count: 1 },
];
const REGIONS: Term[] = [
  { token: "north-america", count: 1 },
  { token: "north-america-east", count: 1 },
];

function view(over: Partial<Parameters<typeof FieldManualView>[0]> = {}) {
  const props = {
    procedures: [FILTER, BOIL],
    remedies: [YARROW, WITCH_HAZEL],
    functions: FUNCTIONS,
    regions: REGIONS,
    activeFunction: null,
    onFunction: vi.fn(),
    activeRegion: null,
    onRegion: vi.fn(),
    have: "",
    onHave: vi.fn(),
    ...over,
  };
  return { props, ...render(<FieldManualView {...props} />) };
}

describe("feasible", () => {
  it("matches through a substitute in both directions and ranks fewest-missing first", () => {
    // `tin can` is inside no material name but IS a substitute; `pot` covers it too.
    const out = feasible([FILTER, BOIL], ["tin can", "fire"]);
    expect(out[0].p.id).toBe("water-boil");
    expect(out[0].missing).toEqual([]);
    // The optional pre-filter cloth never blocks.
    expect(out.some((r) => r.missing.includes("cloth for pre-filtering"))).toBe(false);
  });

  it("drops a procedure the materials touch in no way at all", () => {
    const out = feasible([FILTER, BOIL], ["charcoal"]);
    expect(out.map((r) => r.p.id)).toEqual(["water-improvised-filter"]);
  });

  it("answers nothing for an empty hand", () => {
    expect(feasible([FILTER, BOIL], [])).toEqual([]);
  });
});

describe("growsIn", () => {
  it("walks the region hierarchy in both directions and honours worldwide", () => {
    expect(growsIn(YARROW, "north-america")).toBe(true);
    expect(growsIn(YARROW, "north-america-west")).toBe(true);
    expect(growsIn(WITCH_HAZEL, "north-america")).toBe(true);
    expect(growsIn(WITCH_HAZEL, "north-america-west")).toBe(false);
    expect(growsIn({ ...YARROW, regions: ["worldwide"] }, "patagonia")).toBe(true);
    expect(growsIn(YARROW, null)).toBe(true);
  });

  it("refuses a bare string prefix that is not a region prefix", () => {
    expect(growsIn({ ...YARROW, regions: ["australasia"] }, "asia")).toBe(false);
  });
});

describe("FieldManualView", () => {
  it("renders the standing note before anything else", () => {
    view();
    expect(screen.getByRole("note")).toHaveTextContent(/not medical advice/i);
  });

  /** The safety claim of the whole feature: a look-alike is an ALERT with its tell on screen, not a
   *  detail folded away behind a click. If this ever passes with the tell hidden, the data model's
   *  guarantee has been undone by the view. */
  it("renders every look-alike as an alert carrying the tell that separates it", () => {
    view();
    const alert = screen.getByRole("alert");
    expect(alert).toHaveTextContent("Poison hemlock");
    expect(alert).toHaveTextContent("Lethal.");
    expect(alert).toHaveTextContent(/Hollow stem with purple blotches/);
  });

  it("filters remedies by function and by region", () => {
    const { unmount } = view({ activeFunction: "astringent" });
    expect(screen.queryByTestId("remedy-yarrow")).toBeNull();
    expect(screen.getByTestId("remedy-witch-hazel")).toBeInTheDocument();
    unmount();

    view({ activeRegion: "north-america-west" });
    expect(screen.getByTestId("remedy-yarrow")).toBeInTheDocument();
    expect(screen.queryByTestId("remedy-witch-hazel")).toBeNull();
  });

  /** The filters have to be operable, not merely visible. `Chip` is a span; these must be buttons
   *  with `aria-pressed`, or the whole panel is unreachable from a keyboard. */
  it("exposes the filters as pressable toggle buttons in labelled groups", () => {
    view({ activeFunction: "hemostatic" });
    const group = screen.getByRole("group", { name: "Filter remedies by function" });
    const pressed = within(group).getByRole("button", { pressed: true });
    expect(pressed).toHaveTextContent("hemostatic");
    expect(within(group).getByRole("button", { name: /any function/ })).toHaveAttribute("aria-pressed", "false");
    expect(screen.getByRole("group", { name: "Filter remedies by region" })).toBeInTheDocument();
  });

  it("names the materials input rather than leaning on its placeholder", () => {
    view();
    expect(screen.getByLabelText("Materials you have on hand")).toBeInTheDocument();
  });

  it("shows what the materials in hand support, marking ready and naming what is missing", () => {
    view({ have: "bottle, charcoal" });
    const row = screen.getByTestId("have-water-improvised-filter");
    expect(row).toHaveTextContent("needs 1");
    expect(row).toHaveTextContent("missing: clean sand");
    // Nothing on hand touches boiling, so it is not offered as an answer.
    expect(screen.queryByTestId("have-water-boil")).toBeNull();
  });

  it("says so when a function/region combination has nothing recorded", () => {
    // Astringent narrows to witch hazel, which is recorded for eastern North America only — so
    // asking for it in Europe is a combination the corpus genuinely has nothing for. (Yarrow would
    // NOT have emptied this: `north-america` answers `north-america-east` down the hierarchy.)
    view({ activeFunction: "astringent", activeRegion: "europe" });
    expect(screen.getByText(/Nothing recorded for that combination/)).toBeInTheDocument();
  });
});
